# The reference for chacha20 (pure Python with numpy for the blocks): the
# ChaCha20 stream cipher of RFC 8439 (key bytes 0-31, nonce
# 000000090000004a00000000, counter from 1) over 8 MiB of generated bytes
# (byte i: (i * 2654435761 >> 13) & 255). The block function is checked
# first against the RFC's test vector (section 2.3.2). Prints a checksum
# that weighs every encrypted byte by (i mod 251 + 1), and the first 16
# encrypted bytes in hexadecimal.
import struct
import numpy as np

MASK = 0xFFFFFFFF


def qr(s, a, b, c, d):
    s[a] = (s[a] + s[b]) & MASK; s[d] ^= s[a]; s[d] = (s[d] << 16 | s[d] >> 16) & MASK
    s[c] = (s[c] + s[d]) & MASK; s[b] ^= s[c]; s[b] = (s[b] << 12 | s[b] >> 20) & MASK
    s[a] = (s[a] + s[b]) & MASK; s[d] ^= s[a]; s[d] = (s[d] << 8 | s[d] >> 24) & MASK
    s[c] = (s[c] + s[d]) & MASK; s[b] ^= s[c]; s[b] = (s[b] << 7 | s[b] >> 25) & MASK


def block(key, counter, nonce):
    init = [0x61707865, 0x3320646E, 0x79622D32, 0x6B206574] + list(struct.unpack("<8I", key)) + [counter] + list(struct.unpack("<3I", nonce))
    s = init[:]
    for _ in range(10):
        qr(s, 0, 4, 8, 12); qr(s, 1, 5, 9, 13); qr(s, 2, 6, 10, 14); qr(s, 3, 7, 11, 15)
        qr(s, 0, 5, 10, 15); qr(s, 1, 6, 11, 12); qr(s, 2, 7, 8, 13); qr(s, 3, 4, 9, 14)
    return struct.pack("<16I", *[(a + b) & MASK for a, b in zip(s, init)])


key = bytes(range(32))
nonce = bytes.fromhex("000000090000004a00000000")
assert block(key, 1, nonce).hex().startswith("10f1e7e4d13b5915500fdd1fa32071c4")
n = 1 << 23
data = np.array([((i * 2654435761) >> 13) & 255 for i in range(n)], dtype=np.uint8)
stream = np.frombuffer(b"".join(block(key, 1 + b, nonce) for b in range(n // 64)), dtype=np.uint8)
out = data ^ stream
print(int((out.astype(np.int64) * (np.arange(n) % 251 + 1)).sum()), out[:16].tobytes().hex())
